/// <summary>
/// WolfA 24.04.23
/// </summary>
public class NDXUnitItemMapping extends common
{
}

Method.Source:
/// <summary>
/// Find item mapped to unit
/// </summary>
/// <param name = "_unitOfMeasure">Unit</param>
/// <param name = "_inventTableRecId">Item RecId</param>
/// <param name = "_forUpdate">true or false</param>
/// <returns>NDXUnitItemMapping record</returns>
static public NDXUnitItemMapping find(UnitOfMeasureRecId _unitOfMeasure, RefRecId _inventTableRecId, boolean _forUpdate = false)
{
    NDXUnitItemMapping   unitItemMapping;

    unitItemMapping.selectForUpdate(_forUpdate);

    if (_unitOfMeasure && _inventTableRecId)
    {
        select firstonly unitItemMapping
            where unitItemMapping.RefRecIdUnitOfMeasure == _unitOfMeasure
            && unitItemMapping.RefRecIdInventTable == _inventTableRecId;
    }

    return unitItemMapping;
}

/// <summary>
/// Finds or creates record by Niedax ItemMapping Object
/// </summary>
/// <param name = "_record">Niedax ItemMapping object</param>
/// <returns>NDXUnitItemMapping record</returns>
static public NDXUnitItemMapping findOrCreateByObject(Niedax.Units.NDX_UnitItemMapping _record)
{
    UnitOfMeasure lUnitOfMeasure;
    NDXUnitItemMapping lNDXUnitItemMapping;

    InventTable lInventTable;

    if(_record != null)
    {
        UnitOfMeasureSymbol unitOfMeasureSymbol = _record.UnitId;
        ItemId itemId = _record.ItemId;

        lUnitOfMeasure = UnitOfMeasure::findBySymbol(unitOfMeasureSymbol);

        select firstonly crosscompany lInventTable 
            where lInventTable.ItemId == itemId;

        if(lUnitOfMeasure && lInventTable && lInventTable.Product)
        {
            lNDXUnitItemMapping = NDXUnitItemMapping::find(lUnitOfMeasure.RecId, lInventTable.Product, true);
            lNDXUnitItemMapping.RefRecIdUnitOfMeasure = lUnitOfMeasure.RecId;
            lNDXUnitItemMapping.RefRecIdInventTable = lInventTable.RecId;

            ttsbegin;
            if(!lNDXUnitItemMapping)
            {
                lNDXUnitItemMapping.insert();
            }
            else
            {
                lNDXUnitItemMapping.doUpdate();
            }
            ttscommit;
        }

        if(!lUnitOfMeasure)
        {
            throw error(strFmt('Record UnitOfMeasure %1 does not exist in D365', unitOfMeasureSymbol));
        }

        if(!lUnitOfMeasure)
        {
            throw error(strFmt('Record Item %1 does not exist in D365',itemId));
        }
    }
    return lNDXUnitItemMapping;
}
